#!/bin/bash
# Aplica un pequeno arreglo: el boton "Ficha" del vehiculo (MMA, peso util,
# ADR, grua, plataforma, etc. -- Fase 8Q) no era alcanzable desde ningun
# sitio porque la pestana "Vehiculos" no se muestra en el menu (Raul pidio
# quitarla en Fase 8). Este script reemplaza SOLO
# frontend/src/pages/masters/VehiclesPage.tsx anadiendo un enlace "Ficha"
# junto a la matricula/QR de cada conductor, en la pestana "Conductores".
#
# Ejecutar desde la carpeta raiz del proyecto (la que tiene "frontend" y
# "backend" dentro), con Git Bash:
#   bash apply_fase8q_ficha_vehiculo_desde_conductores.sh
#
# No hace falta Node ni npx para este paso -- no toca la base de datos, solo
# un fichero de la interfaz. Cuando termine, revisa los cambios en GitHub
# Desktop y haz commit + push como siempre para desplegarlo.
set -e
TARGET="frontend/src/pages/masters/VehiclesPage.tsx"
if [ ! -d "frontend" ] || [ ! -d "backend" ]; then
  echo "ERROR: ejecuta este script desde la carpeta raiz del proyecto (debe contener 'frontend' y 'backend')."
  exit 1
fi
echo "" | base64 -d > "$TARGET"
echo "Listo. Se ha actualizado: $TARGET"
